schemaSql:
CREATE TABLE plans (
  id INTEGER PRIMARY KEY,
  name TEXT,
  monthly_price REAL
);
CREATE TABLE users (
  id INTEGER PRIMARY KEY,
  name TEXT,
  signup_date TEXT
);
CREATE TABLE subscriptions (
  id INTEGER PRIMARY KEY,
  user_id INTEGER,
  plan_id INTEGER,
  started_at TEXT,
  ended_at TEXT
);

